OUT=/tmp/opencode/wiki_scan
# total size of matching conv files
SUM=0; N=0
while read -r f; do s=$(stat -c%s "$f"); SUM=$((SUM+s)); N=$((N+1)); done < "$OUT/conv_files.txt"
echo "MATCHING_CONVS=$N TOTAL_BYTES=$SUM"
# timestamps ms->s
grep -aE "wiki|ويكي|wikillm" ~/.gemini/antigravity-cli/history.jsonl | grep -oE '"timestamp":[0-9]+' | sed 's/.*://' | sort -u | while read -r ms; do date -u -d @$((ms/1000)) '+%Y-%m-%d %H:%M:%S UTC'; done
# conversation_metadata wiki entries
python3 - <<'PY'
import json,re
p="/root/.gemini/antigravity-cli/cache/conversation_metadata.json"
try:
  data=json.load(open(p))
except Exception as e:
  print("err",e); raise SystemExit
# structure unknown
pat=re.compile(r"wiki|ويكي|wikillm",re.I)
def walk(o,path=""):
  if isinstance(o,dict):
    for k,v in o.items(): walk(v,path+"/"+str(k))
  elif isinstance(o,list):
    for i,v in enumerate(o): walk(v,path+f"[{i}]")
  elif isinstance(o,str):
    if pat.search(o): print(path, "=>", o[:200])
walk(data)
# also count matching conversation ids if dict keyed by id
if isinstance(data,dict):
  keys=[k for k in data if pat.search(str(k))]
  print("key matches",len(keys))
  # try values that are dicts with title
  hits=[]
  for k,v in data.items():
    s=json.dumps(v,ensure_ascii=False) if not isinstance(v,str) else v
    if pat.search(s):
      title=""
      if isinstance(v,dict):
        title=v.get("title") or v.get("summary") or v.get("display") or ""
      hits.append((k,str(title)[:120]))
  print("value hits",len(hits))
  for h in hits[:30]: print(h)
elif isinstance(data,list):
  hits=[x for x in data if pat.search(json.dumps(x,ensure_ascii=False))]
  print("list hits",len(hits))
  for h in hits[:30]: print(str(h)[:200])
PY
# antigravity_bypass elsewhere
find /root -maxdepth 3 -iname "*bypass*" 2>/dev/null | head -20
# check if sqlite3 available for real wiki message counts in top convs
command -v sqlite3 || echo no-sqlite3

